"use client";

import React, { useRef, useState } from "react";
import { Search } from "lucide-react";
import { cn } from "@/lib/utils";

export interface SpotlightInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> {
  label?: string;
  icon?: React.ReactNode;
  spotlightColor?: string;
}

export function SpotlightInput({
  label,
  icon = <Search className="h-4 w-4 text-zinc-400" />,
  spotlightColor = "rgba(0, 102, 255, 0.25)",
  className,
  placeholder = "Search or type command...",
  ...props
}: SpotlightInputProps) {
  const divRef = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [opacity, setOpacity] = useState(0);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!divRef.current) return;
    const rect = divRef.current.getBoundingClientRect();
    setPosition({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  const handleMouseEnter = () => setOpacity(1);
  const handleMouseLeave = () => setOpacity(0);

  return (
    <div className="w-full max-w-sm font-sans select-none space-y-1.5">
      {label && <label className="text-xs font-bold text-zinc-500 uppercase tracking-wider">{label}</label>}
      <div
        ref={divRef}
        onMouseMove={handleMouseMove}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        className={cn(
          "relative flex items-center gap-2.5 rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white/90 dark:bg-zinc-900/90 px-3.5 py-2.5 shadow-xs transition-all overflow-hidden focus-within:ring-2 focus-within:ring-[#0066FF]/40",
          className
        )}
      >
        <div
          className="pointer-events-none absolute -inset-px transition-opacity duration-300 rounded-2xl"
          style={{
            opacity,
            background: `radial-gradient(400px circle at ${position.x}px ${position.y}px, ${spotlightColor}, transparent 80%)`,
          }}
        />
        <span className="shrink-0 relative z-10">{icon}</span>
        <input
          placeholder={placeholder}
          className="w-full bg-transparent text-xs font-medium text-zinc-900 dark:text-zinc-100 placeholder:text-zinc-400 outline-none border-none relative z-10"
          {...props}
        />
      </div>
    </div>
  );
}

export default SpotlightInput;
